/** Accepts only a same-locale invitation generated by Iroko. */
export function invitationReturn(value: unknown, locale: string): string | null {
  const prefix = `/${locale}/auth/accept-invitation?token=`;
  if (typeof value !== 'string' || !value.startsWith(prefix)) return null;
  const token = value.slice(prefix.length);
  return token.length === 64 && /^[0-9a-f]+$/i.test(token) ? `${prefix}${token}` : null;
}
